function gameStarterReference(starter) {
  if (starter === undefined)
    return;
  if (starter === "game-scribble-sky-hop-v1")
    return "game-legacy-scribble-sky-hop.md";
  for (const [choice, entry] of Object.entries(GAME_STARTER_CATALOG)) {
    if (entry.id === starter)
      return entry.reference;
    if (PREVIOUS_GAME_STARTERS[choice]?.includes(starter)) {
      const revision = Number(starter.match(/-v([0-9]+)$/)?.[1]);
      if (choice === "td" && revision < 57)
        return "game-legacy-td.md";
      if (choice === "scroller" && revision < 62)
        return "game-legacy-scroller.md";
      if (choice === "rts" && revision < 55)
        return "game-legacy-rts.md";
      return entry.reference;
    }
    if (choice in PREVIOUS_GAME_STARTERS && choice !== "generic-multiplayer" && choice !== "vertical-platformer" && (starter === `game-${choice}-v1` || choice === "generic" && starter === "game-generic-v2")) {
      return `game-legacy-${choice}.md`;
    }
  }
  return;
}

