// mcp/init/webStarterWindowsCommands.ts
function webStarterWindowsCommands(source) {
  const pkg = JSON.parse(source);
  if (pkg.scripts?.dev !== "NODE_ENV=development tsx watch server/_core/index.ts" || pkg.scripts?.start !== "NODE_ENV=production node dist/index.js") {
    throw new Error("Unexpected Web starter commands");
  }
  pkg.scripts.dev = `node -e "process.env.NODE_ENV='development';process.argv.splice(1,0,'tsx');import('tsx/cli')" -- watch server/_core/index.ts`;
  pkg.scripts.start = `node -e "process.env.NODE_ENV='production';import('./dist/index.js')"`;
  return JSON.stringify(pkg, null, 2) + `
`;
}

