      configuration_status: entry.settingsError ? "error" : entry.restartRequired ? "restart_required" : entry.settingsHash ? "loaded" : "not_loaded",
      settings_hash: entry.settingsHash,
      recovery_mode: entry.registration.launch_state_file ? "restart" : "reconnect",
      ...entry.recoveryWarning ? { recovery_note: entry.recoveryWarning } : {},
