// shared/staticDigest.ts
import crypto13 from "node:crypto";
import fs27 from "node:fs";
import path34 from "node:path";
function sha256File(filePath) {
  return crypto13.createHash("sha256").update(fs27.readFileSync(filePath)).digest("hex");
}
function sha256Directory(directory3) {
  if (!fs27.statSync(directory3, { throwIfNoEntry: false })?.isDirectory()) {
    throw new Error(`Directory does not exist: ${directory3}`);
  }
  const hash2 = crypto13.createHash("sha256");
  for (const filePath of listDirectoryFiles(directory3)) {
    const relativePath = path34.relative(directory3, filePath).split(path34.sep).join("/");
    hash2.update(relativePath);
    hash2.update("\x00");
    hash2.update(sha256File(filePath));
    hash2.update("\x00");
  }
  return hash2.digest("hex");
}
function listDirectoryFiles(directory3) {
  return fs27.readdirSync(directory3, { withFileTypes: true }).sort((left, right) => left.name.localeCompare(right.name)).flatMap((entry) => {
    const filePath = path34.join(directory3, entry.name);
    return entry.isDirectory() ? listDirectoryFiles(filePath) : [filePath];
  });
}

// shared/mobileExpoStarterAsset.ts
var FORBIDDEN_DIRECTORY_NAMES = new Set([
  ".cache",
  ".expo",
  ".git",
  ".pnpm-store",
  ".turbo",
  "build",
  "coverage",
  "dist",
  "node_modules"
]);
function isForbiddenFileName(name) {
  return name === ".DS_Store" || name === ".env" || name.startsWith(".env.") || name.endsWith(".log");
}
function assertStarterEntries(directory3, relativeDirectory = "") {
  const entries2 = fs28.readdirSync(directory3, { withFileTypes: true });
  for (const entry of entries2) {
    const relativePath = path35.join(relativeDirectory, entry.name).split(path35.sep).join("/");
    if (entry.isSymbolicLink()) {
      throw new Error(`frozen starter contains a symbolic link: ${relativePath}`);
    }
    if (entry.isDirectory()) {
      if (FORBIDDEN_DIRECTORY_NAMES.has(entry.name)) {
        throw new Error(`frozen starter contains a forbidden directory: ${relativePath}`);
      }
      assertStarterEntries(path35.join(directory3, entry.name), relativePath);
      continue;
    }
    if (!entry.isFile()) {
      throw new Error(`frozen starter contains an unsupported entry: ${relativePath}`);
    }
    if (fs28.statSync(path35.join(directory3, entry.name)).mode & 73) {
      throw new Error(`frozen starter contains an executable file: ${relativePath}`);
    }
    if (isForbiddenFileName(entry.name)) {
      throw new Error(`frozen starter contains a forbidden file: ${relativePath}`);
    }
  }
}
function assertFrozenStarter(directory3, label, expectedRevision) {
  const root = fs28.lstatSync(directory3, { throwIfNoEntry: false });
  if (!root?.isDirectory() || root.isSymbolicLink()) {
    throw new Error(`[build-package] ${label} is not a regular directory: ${directory3}`);
  }
  assertStarterEntries(directory3);
  const actualRevision = sha256Directory(directory3);
  if (actualRevision !== expectedRevision) {
    throw new Error(`[build-package] ${label} revision mismatch: expected ${expectedRevision}, got ${actualRevision}`);
  }
  return actualRevision;
}

