// mcp/gameBlueprintPlanning.ts
async function collectGameBlueprintCatalogEvidence(client, queries, signal) {
  const unknown = (reason) => ({ status: "unknown", searches: [], reason });
  throwIfAborted(signal);
  if (!client.gameAssetCatalogSearch || !queries.length)
    return unknown("assessment_unavailable");
  const deadline = AbortSignal.any([...signal ? [signal] : [], AbortSignal.timeout(GAME_BLUEPRINT_CATALOG_LIMITS.searchTimeoutMs)]);
  for (let attempt = 0;attempt < 2; attempt++) {
    let snapshotId;
    let snapshotChanged = false;
    let unavailable = false;
    const controller = new AbortController;
    const searchSignal = AbortSignal.any([deadline, controller.signal]);
    const searches = [];
    async function batch(items) {
      let index = 0;
      async function worker() {
        while (index < items.length && !searchSignal.aborted) {
          const item = items[index++];
          try {
            const raw = await client.gameAssetCatalogSearch({
              query: item.recovery ? item.query.recoveryQuery : item.query.query,
              ...snapshotId ? { snapshotId } : {},
              limit: GAME_BLUEPRINT_CATALOG_LIMITS.candidatesPerSearch,
              ...!item.recovery && item.query.filters ? { filters: item.query.filters } : {}
            }, searchSignal);
            searchSignal.throwIfAborted();
            const result2 = projectGameBlueprintCatalogSearch(item.query, raw, { recovery: item.recovery });
            if (snapshotId && result2.snapshotId !== snapshotId) {
              snapshotChanged = true;
              controller.abort();
              return;
            }
            snapshotId ??= result2.snapshotId;
            searches.push(result2);
          } catch (error2) {
            if (searchSignal.aborted)
              return;
            const reason = gameAssetCatalogErrorReason(error2);
            if (reason === "game_asset_catalog_snapshot_changed" || reason === "game_asset_catalog_snapshot_retired")
              snapshotChanged = true;
            else
              unavailable = true;
            controller.abort();
            return;
          }
        }
      }
      await Promise.all([worker(), worker()]);
    }
    await batch(queries.map((query) => ({ query, recovery: false })));
    throwIfAborted(signal);
    if (deadline.aborted)
      return unknown("search_timeout");
    if (snapshotChanged)
      continue;
    if (unavailable || searches.length !== queries.length)
      return unknown("search_unavailable");
    const recovery = queries.filter((query) => query.recoveryQuery && gameBlueprintCatalogSearchNeedsRecovery(searches.find((search) => search.queryId === query.id))).slice(0, GAME_BLUEPRINT_CATALOG_LIMITS.recoveryQueries).map((query) => ({ query, recovery: true }));
    await batch(recovery);
    throwIfAborted(signal);
    if (deadline.aborted)
      return unknown("search_timeout");
    if (snapshotChanged)
      continue;
    if (unavailable || searches.length !== queries.length + recovery.length)
      return unknown("search_unavailable");
    searches.sort((a, b) => queries.findIndex((query) => query.id === a.queryId) - queries.findIndex((query) => query.id === b.queryId) || Number(a.recovery) - Number(b.recovery));
    const evidence = { status: "complete", snapshotId, searches };
    while (new TextEncoder().encode(JSON.stringify(evidence)).length > GAME_BLUEPRINT_CATALOG_LIMITS.evidenceBytes) {
      const crowded = searches.filter((search) => search.candidates.length > 1);
      const removable = crowded.length ? crowded : searches.filter((search) => search.candidates.length);
      const target = removable.sort((a, b) => JSON.stringify(b.candidates).length - JSON.stringify(a.candidates).length)[0];
      if (!target)
        return unknown("evidence_limit_or_invalid_metadata");
      target.candidates.pop();
      target.exhausted = false;
      target.truncated = true;
    }
    try {
      return parseGameBlueprintCatalogEvidence(evidence, queries);
    } catch {
      return unknown("evidence_limit_or_invalid_metadata");
    }
  }
  return unknown("snapshot_changed");
}

