    const beforeRoot = path57.join(staging, "before"), afterRoot = path57.join(staging, "after");
    await initializeGameProject(beforeRoot, { resourceId, artifactRevision: receipt.source, description: state.description });
    await initializeGameProject(afterRoot, { resourceId, artifactRevision: receipt.target, description: state.description });
